// Написан вручную (несколько ролей: авторы user2/reg4 создают сторис, зритель reg1 смотрит, user2 видит ответ в чате).
// spec: .qa/e2e/specs/stories-viewer.md (раздел 2) · кейсы .qa/tests/stories-viewer/SV-03,04,08,09
// @data: user2 создаёт 2 сторис и reg4 — 1 сторис «QA-AUTO sv …» (в конце удаляются через меню автора);
// reg1 отправляет ответ «QA-AUTO sv …» (удалить нельзя — RLS story_replies, остаётся в чате reg1↔user2, в список чистки);
// «אהבתי» reg1→user2 — лайк и мэтч 8571b9f7 уже есть, новых данных нет. reg5 сторис не создаёт (лист модерации).
// Проект data — по одному; устройство задано здесь: iPhone 13 Mini (WebKit), как в проекте iphone.
import { test, expect, devices, type Page } from '@playwright/test';
import { captureApi, restGet, restDelete, myMatches, rowsWith, matchIdOf, type Row } from '../_shared/api';
import {
  iphoneAs, closeAs, createStory, deleteOwnStory, openDiscover, groupsInRow, requireGroups, openAuthor, expectShowing,
  fills, tapSide, replyBox, likeButton, type Group, type FeedStory,
} from './viewer-helpers';

test.use({ ...devices['iPhone 13 Mini'] });

const stamp = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
const CAP = { u2a: `QA-AUTO sv ${stamp} 1/2`, u2b: `QA-AUTO sv ${stamp} 2/2`, r4: `QA-AUTO sv ${stamp} reg4` };
const created: { role: 'user2' | 'reg4'; story?: FeedStory; caption: string }[] = [
  { role: 'user2', caption: CAP.u2a },
  { role: 'user2', caption: CAP.u2b },
  { role: 'reg4', caption: CAP.r4 },
];

test.describe('מסך צפייה בסיפור — переходы, ответ, лайк', () => {
  test.describe.configure({ mode: 'serial', timeout: 180_000 });

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    for (const role of ['user2', 'reg4'] as const) {
      const p = await iphoneAs(browser, role);
      try {
        for (const c of created.filter((x) => x.role === role)) await createStory(p, c.caption);
      } finally {
        await closeAs(p, role);
      }
    }
    const viewer = await iphoneAs(browser, 'reg1');
    try {
      const feed = await openDiscover(viewer);
      for (const c of created) c.story = feed.find((s) => s.caption === c.caption);
      for (const c of created) expect(c.story, `reg1 видит в ленте новую сторис «${c.caption}» (аудитория #a85b92)`).toBeTruthy();
    } finally {
      await closeAs(viewer, 'reg1');
    }
  });

  test.afterAll(async ({ browser }) => {
    for (const role of ['user2', 'reg4'] as const) {
      const mine = created.filter((c) => c.role === role && c.story);
      if (!mine.length) continue;
      const p = await iphoneAs(browser, role);
      try {
        for (const c of mine) await deleteOwnStory(p, c.story!.id);
      } finally {
        await closeAs(p, role);
      }
    }
  });

  // Лента reg1 и группа user2 (с её новыми сторис).
  async function viewerWithUser2(browser: import('@playwright/test').Browser): Promise<{ page: Page; groups: Group[]; u2: Group }> {
    const page = await iphoneAs(browser, 'reg1');
    const groups = await groupsInRow(page, await openDiscover(page));
    const u2 = groups.find((g) => g.authorId === created[0].story!.author_id)!;
    expect(u2.stories.length, 'у user2 ≥2 сторис').toBeGreaterThanOrEqual(2);
    return { page, groups, u2 };
  }

  test('Тап слева — следующая сторис автора, тап справа — предыдущая @iphone @data (#f71f8d)', async ({ browser }) => {
    const { page, u2 } = await viewerWithUser2(browser);
    try {
      await openAuthor(page, u2);
      await expectShowing(page, u2, 0);
      await tapSide(page, 'left');
      // AC 4: «מאפשר מעבר בין סיפורים»; просмотренный сегмент — полный (Р4.1).
      await expectShowing(page, u2, 1);
      expect((await fills(page, u2.name))[0]).toBe(1);
      await tapSide(page, 'right');
      await expectShowing(page, u2, 0);
    } finally {
      await closeAs(page, 'reg1');
    }
  });

  test('После последней сторис автора — следующий автор, тап справа — обратно к предыдущему @iphone @data (#f71f8d)', async ({ browser }) => {
    const page = await iphoneAs(browser, 'reg1');
    try {
      const [a, b] = requireGroups(await groupsInRow(page, await openDiscover(page)), 2);
      await openAuthor(page, a);
      for (let i = 0; i < a.stories.length; i++) {
        await expectShowing(page, a, i);
        await tapSide(page, 'left');
      }
      // AC 4: переход к следующему автору ленты; сегменты — по его сторис.
      await expectShowing(page, b, 0);
      await tapSide(page, 'right');
      await expectShowing(page, a, a.stories.length - 1);
    } finally {
      await closeAs(page, 'reg1');
    }
  });

  test('Ответ: поле «תגובה ל<автор>…», ответ уходит той сторис, где начали печатать, автор видит его в чате @iphone @data (#f71f8d)', async ({ browser }) => {
    const { page, u2 } = await viewerWithUser2(browser);
    const author = await iphoneAs(browser, 'user2');
    const text = `QA-AUTO sv ${stamp} reply — תגובה לבדיקה אוטומטית`;
    try {
      await openAuthor(page, u2);
      await expectShowing(page, u2, 0);
      const story = u2.stories[0];
      // AC 5: поле ответа с именем автора.
      await expect(replyBox(page)).toHaveAccessibleName(`תגובה ל${u2.name}…`);
      await replyBox(page).click();
      // Печатаем дольше, чем длится одна сторис (~5 с): таймер должен стоять, сторис — не смениться (наблюдение 29.10).
      await replyBox(page).pressSequentially(text, { delay: 120 });
      const sent = page.waitForResponse((r) => r.url().includes('/rest/v1/story_replies') && r.request().method() === 'POST');
      await replyBox(page).press('Enter');
      const res = await sent;
      // AC 6: «מאפשר שליחת תגובה לסיפור».
      expect(res.status()).toBe(201);
      expect(res.request().postDataJSON()).toMatchObject({ story_id: story.id, to_user_id: u2.authorId, body: text });
      await expect(page.getByText("התגובה נשלחה לצ'אט")).toBeVisible();
      const viewerId = String(res.request().postDataJSON().author_id);

      // Автор видит ответ в чате с reg1 («הגיב/ה לסטורי שלך»).
      const api = await captureApi(author, '/discover');
      const match = rowsWith(await myMatches(api), viewerId)[0];
      expect(match, 'мэтч user2↔reg1 (8571b9f7)').toBeTruthy();
      await author.goto(`/chat/${matchIdOf(match)}`);
      await expect(author.getByText(text)).toBeVisible();

      // Очистка: попытка удалить ответ от имени зрителя (RLS обычно не даёт — тогда в список чистки).
      const me = await captureApi(page, '/discover');
      const rows: Row[] = await (await restGet(me, `story_replies?select=id&body=eq.${encodeURIComponent(text)}`)).json();
      for (const r of rows) {
        const del = await restDelete(me, `story_replies?id=eq.${r.id}`);
        const gone: Row[] = del.ok() ? await del.json() : [];
        if (!gone.length) test.info().annotations.push({ type: 'cleanup', description: `story_replies ${r.id} «${text}» не удалён (RLS) — в список чистки` });
      }
    } finally {
      await closeAs(author, 'user2');
      await closeAs(page, 'reg1');
    }
  });

  test('«אהבתי» из сторис — лайк профилю автора (rpc/swipe like) @iphone @data (#f71f8d)', async ({ browser }) => {
    const { page, u2 } = await viewerWithUser2(browser);
    try {
      await openAuthor(page, u2);
      await expectShowing(page, u2, 0);
      const swipe = page.waitForResponse((r) => r.url().includes('/rpc/swipe') && r.request().method() === 'POST');
      await likeButton(page).click();
      const res = await swipe;
      // AC 8: «מאפשר סימון אהבתי לפרופיל המפרסם מתוך הסיפור» — обычный лайк (#b76c3b).
      expect(res.ok()).toBeTruthy();
      expect(res.request().postDataJSON()).toMatchObject({ p_target: u2.authorId, p_kind: 'like' });
    } finally {
      await closeAs(page, 'reg1');
    }
  });
});
